          "dependency_level": 0,
          "strategy": "Differentiate the radial error-function potential, verify its distributional source by the flux at the origin, and compute the finite self part.",
          "justified_by": [],
          "provenance": {
            "statement": "literature-derived",
            "proof": "ai-altered"
