  {
    "id": "def-na-finite-interval-oscillatory-integral",
    "kind": "definition",
    "title": "Finite-interval oscillatory integral and phase convention",
    "deps": [
      "cor-complex-exponential-cartesian-form-modulus-and-eulers-identity",
