              },
              {
                "title": "CGAL 6.3 User Manual, 3D Triangulations",
                "url": "https://cgal.github.io/9465/doc/Triangulation_3/index.html"
              }
            ]
          }
        },
        {
          "id": "lem-complete-ordered-field-is-archimedean",
          "kind": "lemma",
          "title": "A complete ordered field has cofinal canonical integers",
          "deps": [],
          "dependency_level": 0,
          "statement": "Let $F$ be a Dedekind-complete ordered field with $1_F>0$. For every $x\\in F$, some canonical integer $n\\cdot1_F$ satisfies $x<n\\cdot1_F$.",
          "source_path": "items/lem-complete-ordered-field-is-archimedean.md",
          "provenance": {
