  {
    "id": "lem-voronoi-vertex-empty-circle",
    "kind": "lemma",
    "title": "A Voronoi vertex has a common empty circle of nearest sites",
    "deps": [
      "def-indexed-geometric-site-set"
    ],
    "dependency_level": 1,
    "statement": "Let $P\\subset\\mathbb R^2$ be finite and nonempty, and define $V(p)=\\{x:\\|x-p\\|^2\\le\\|x-q\\|^2\\ \\text{for all }q\\in P\\}$. If $x$ belongs to at least three distinct cells, then all sites whose cells contain $x$ lie on one circle centered at $x$, no site lies strictly inside that circle, and their convex hull is a polygon with those sites as its vertices.",
    "source_path": "items/lem-voronoi-vertex-empty-circle.md",
    "provenance": {
      "statement": "literature-derived",
      "proof": "ai-altered"
    },
    "sources": {
