  {
    "id": "lem-large-delaunay-supertriangle-exists",
    "kind": "lemma",
    "title": "A dyadic supertriangle contains the sites and excludes every input circumcircle",
    "deps": [
      "def-indexed-geometric-site-set",
      "def-planar-delaunay-voronoi-structures",
      "lem-complete-ordered-field-is-archimedean"
    ],
    "dependency_level": 3,
    "statement": "For every finite full-dimensional dyadic planar site set, a dyadic supertriangle can be chosen to contain every input site strictly and to have all three vertices strictly outside every circumcircle through a noncollinear input triple. If the input has no three collinear and no four cocircular sites, the supertriangle can additionally be chosen so the augmented set has no three collinear sites and no four cocircular sites.",
    "source_path": "items/lem-large-delaunay-supertriangle-exists.md",
    "provenance": {
