        {
          "id": "lem-square-root-kalman-prearray-qr-error-bound",
          "kind": "lemma",
          "title": "Product and Householder QR errors bound the represented joint covariance",
          "deps": [
            "def-operationwise-real-complex-floating-point-model-with-sqrt-and-fma",
