        {
          "id": "thm-square-root-kalman-finite-procedure-status",
          "kind": "theorem",
          "title": "The square-root Kalman procedure terminates with a finite status and operation-count bound",
          "deps": [
            "alg-finite-budget-square-root-kalman-filter",
