          },
          "sources": {
            "references": [
              {
                "title": "DLMF, §7.6, Series Expansions",
                "url": "https://dlmf.nist.gov/7.6"
              },
              {
                "title": "DLMF, §15.2(i), Gauss Series",
                "url": "https://dlmf.nist.gov/15.2"
