        {
          "id": "alg-certified-scaled-spherical-bessel-evaluation",
          "kind": "algorithm",
          "title": "Finite exact-interval evaluation of scaled spherical Bessel values",
          "deps": [
            "def-spherical-bessel-evaluation-contract",
            "def-factorial-and-falling-factorial",
