        }
      ]
    }
  },
  {
    "id": "thm-godunov-flux-is-consistent-and-conservative",
    "kind": "theorem",
    "title": "The local Godunov flux is consistent and conservative",
    "deps": [
      "def-godunov-flux-from-a-local-riemann-solver",
      "thm-local-small-data-riemann-solver"
    ],
    "dependency_level": 8,
    "statement": "For all equal states $u$ in the local solver neighborhood,\n$G(u,u)=f(u)$. For any finite periodic array of length $n\\ge1$ whose adjacent pairs lie in the\nlocal flux domain, define the update (indices modulo $n$)\n$$U_j^{new}=U_j-\\nu\\bigl(G(U_j,U_{j+1})-G(U_{j-1},U_j)\\bigr).$$\nFor any scalar $\\nu$, this update using one two-state flux at each interface\npreserves the sum of cell states.",
    "provenance": {
      "statement": "literature-derived",
      "proof": "ai-generated"
    },
    "sources": {
