          "sources": {
            "references": [
              {
                "title": "R. Eymard, T. Gallouët, and R. Herbin, Finite Volume Methods, Handbook of Numerical Analysis, Vol. VII, 2000; complete updated author text",
                "url": "https://raphaeleh.github.io/PUBLI/bookevol.pdf",
