                "url": "https://cs.nyu.edu/~widlund/SD_rev_tutorial.pdf"
              }
            ]
          }
        },
        {
          "id": "lem-pe26-complementary-primal-dual-spectrum",
          "kind": "lemma",
          "title": "Complementary primal and dual projections share nonunit spectrum",
          "deps": [
            "def-pe26-scaled-averaging-and-bddc-preconditioner",
            "def-pe26-feti-dp-dual-system-and-preconditioner"
          ],
          "justified_by": [],
          "dependency_level": 6,
          "statement": "Let $V,U_1,U_2$ be finite-dimensional real vector spaces, let $A:V\\to V'$ be symmetric positive definite, and let $L_i:V\\to U_i$, $T_i:U_i\\to V$ satisfy $L_iT_i=I_{U_i}$ for $i=1,2$ and $T_1L_1+T_2L_2=I_V$. Then the operators\n\n$$G_1=(L_1A^{-1}L_1^T)(T_1^TAT_1),\\qquad G_2=(T_2^TAT_2)(L_2A^{-1}L_2^T)$$\n\nhave the same eigenvalues, with the same multiplicities, except possibly at the eigenvalue $1$.",
          "source_path": "items/lem-pe26-complementary-primal-dual-spectrum.md",
